// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount) public {
        depositAmount = bound(depositAmount, 1, 100 ether);
        withdrawAmount = bound(withdrawAmount, 1, depositAmount);

        address caller = address(0x1234);
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        (bool success, ) = address(c).call{value: depositAmount}("");
        require(success, "deposit failed");

        uint256 balanceBefore = address(caller).balance;

        vm.prank(caller);
        c.withdraw();

        assertTrue(address(caller).balance == balanceBefore + depositAmount);
    }
}
